export var getSeasonalityComposite = async function(symbol, years, method) {
  var allCloses, i, len, normalizedCloses, yearCloses;
  allCloses = (await getHistoricCloseData(symbol, years));
  normalizedCloses = [];
  for (i = 0, len = allCloses.length; i < len; i++) {
    yearCloses = allCloses[i];
    normalizedCloses.push(normalizeYearData(yearCloses));
  }
  return calculateSeasonalityComposite(normalizedCloses, method);
};

//###########################################################
export var getSeasonalityCompositeMonthly = async function(symbol, years, method) {
  var monthlyCloses, months, today;
  today = new Date();
  months = today.getMonth(); // for current year, january on current year is 0
  months += years * 12; // for all further years, take full year of 12 months
  //# so if we go back 0 years and current year is at january then we only take current month.
  //# if we go back 0 years and current month is June then we go back 5 month + current month
  //# if we go back 5 years and current month is June then we go back 60 + 5 month + current month
  monthlyCloses = (await getHistoricCloseDataMonthly(symbol, months));
  return calculateSeasonalityComposite(monthlyCloses, method);
};

//###########################################################
export var getSeasonalityCompositeWeekly = async function(symbol, years, method) {
  var today, weeklyCloses, weeks;
  today = new Date();
  weeks = Math.floor(utl.getDayOfYear(today) / 7); // same scheme as monthly
  weeks += years * 52;
  weeklyCloses = (await getHistoricCloseDataWeekly(symbol, weeks));
  return calculateSeasonalityComposite(weeklyCloses, method);
};

